import java.util.Scanner;

public class Main {
    public static double absolute(double value) {
        return (value < 0) ? -value : value;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int x = scanner.nextInt();
        int y = scanner.nextInt();
        int n = scanner.nextInt();
        int bestA = 0, bestB = 1;
        double minDiff = 1e15;
        double ratio = (double) x / y;

        for (int j = 1; j <= n; ++j) {
            int left = 0, right = 1000000000;
            while (right - left > 10) {
                int m1 = left + (right - left) / 3;
                int m2 = right - (right - left) / 3;
                double diff1 = absolute(ratio - (double) m1 / j);
                double diff2 = absolute(ratio - (double) m2 / j);
                if (diff1 > diff2)
                    left = m1;
                else
                    right = m2;
            }
            for (int i = left; i <= right + 3; ++i) {
                double currentDiff = absolute(ratio - (double) i / j);
                if (currentDiff < minDiff - 1e-15) {
                    minDiff = currentDiff;
                    bestA = i;
                    bestB = j;
                }
            }
        }
        System.out.println(bestA + "/" + bestB);
        scanner.close();
    }
}
